    const next = submissionReady ? pick("论文侧闭环已经完成。下一步是人工作者责任确认、OpenReview 账号/元数据核验并真实提交；只有收到外部人工 submission authority 后，ledger 才允许 SUBMISSION_READY → SUBMITTED。","The paper-side closure is complete. Next comes human author responsibility/signoff, OpenReview account/metadata verification, and the real submission; the ledger permits SUBMISSION_READY → SUBMITTED only with external human submission authority.") : current === "TARGETED_REPAIR" ? pick("完成针对 Mock PC 拒稿风险的文稿修复，然后进入 Claim Audit。当前不自动新增实验；只有科研合同被正式重开时，实验才走独立授权流程。","Repair the manuscript against the Mock PC rejection risks, then enter Claim Audit. No experiment is auto-created; experiments require a separately reopened scientific contract and authority path.") : pick(`按 canonical Paper Ledger 从 ${paperStageLabel(current)} 继续下一项未完成门。`,`Continue from ${paperStageLabel(current)} to the next incomplete canonical Paper Ledger gate.`);
